const cfg = $input.first().json;
const msg = $('When New Email Received').first().json;

// Gmail trigger (simplified output): From is a string like 'Jane Doe <user@example.com>'.
// Fall back to the Outlook-style object shape defensively.
let senderEmail = '';
let senderName = '';
const fromRaw = msg.From || msg.from || '';
if (typeof fromRaw === 'string') {
  const m = fromRaw.match(/<([^>]+)>/);
  senderEmail = (m ? m[1] : fromRaw).toLowerCase().trim();
  senderName = fromRaw.replace(/<[^>]*>/, '').replace(/"/g, '').trim() || senderEmail;
} else if (fromRaw && fromRaw.emailAddress) {
  senderEmail = (fromRaw.emailAddress.address || '').toLowerCase().trim();
  senderName = fromRaw.emailAddress.name || senderEmail;
}

const subject = msg.Subject || msg.subject || '';
let bodyHtml = '';
if (msg.html) { bodyHtml = msg.html; }
else if (msg.text) { bodyHtml = msg.text; }
else if (msg.snippet) { bodyHtml = msg.snippet; }
else if (msg.body && msg.body.content) { bodyHtml = msg.body.content; }

const bodyText = String(bodyHtml)
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 4000);

const domains = (cfg.allowedSenderDomains || '').toLowerCase().split(',').map(function(d){ return d.trim(); }).filter(function(d){ return d; });
const senderDomain = senderEmail.split('@')[1] || '';
const domainOk = domains.length === 0 || domains.indexOf(senderDomain) !== -1;

const keyword = (cfg.subjectKeyword || '').toLowerCase().trim();
const keywordOk = keyword === '' || subject.toLowerCase().indexOf(keyword) !== -1 || bodyText.toLowerCase().indexOf(keyword) !== -1;

return [{ json: Object.assign({}, cfg, {
  authorized: domainOk && keywordOk,
  senderEmail: senderEmail,
  senderName: senderName,
  subject: subject,
  bodyText: bodyText,
  messageId: msg.id,
  threadId: msg.threadId || ''
}) }];

const req = $('Validate Sender & Extract Request').first().json;
// Google Sheets read returns one item per row
const rawItems = $input.all().map(function (i) { return i.json; });
const catalog = [];
for (const f of rawItems) {
  if (!f || !f.FileId) continue;
  catalog.push({
    docType: (f.Title || '').toString(),
    aliases: (f.Aliases || '').toString(),
    fileId: (f.FileId || '').toString(),
    fileName: (f.FileName || '').toString()
  });
}
if (catalog.length === 0) {
  throw new Error('Template catalog is empty — check catalogSpreadsheetId / catalogSheet and that rows have the FileId column populated.');
}
const catalogText = catalog.map(function(c, i){
  return (i + 1) + '. ' + c.docType + (c.aliases ? ' (aliases: ' + c.aliases + ')' : '') + ' [fileId: ' + c.fileId + ']';
}).join('\n');
return [{ json: Object.assign({}, req, { catalog: catalog, catalogText: catalogText }) }];

