const record = $input.first().json;
let text = '';
try {
  text = record.output[0].content[0].text || '';
} catch (e) {
  throw new Error('Unexpected AI response structure: ' + JSON.stringify(record).substring(0, 300));
}
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```[a-z]*\n?/, '').replace(/```\s*$/, '').trim();
}
let decision;
try {
  decision = JSON.parse(text);
} catch (e) {
  throw new Error('AI did not return valid JSON: ' + text.substring(0, 300));
}
const req = $('Build Template Catalog for AI').first().json;
let matched = decision.matched === true;
let entry = null;
if (matched) {
  entry = (req.catalog || []).find(function(c){ return c.fileId === decision.fileId; });
  if (!entry) {
    matched = false;
    decision.reason = 'AI returned a fileId not present in the catalog.';
  }
}
const recipientName = (decision.recipientName || '').toString().trim();
const docTypeLabel = entry ? entry.docType : ((decision.docTypeLabel || '').toString());
const safeName = recipientName.replace(/[^a-zA-Z0-9]/g, '') || 'Recipient';
const safeLabel = (docTypeLabel || 'Document').replace(/[^a-zA-Z0-9 ]/g, '').replace(/ /g, '_');
return [{ json: Object.assign({}, req, {
  matched: matched,
  fileId: entry ? entry.fileId : '',
  templateFileName: entry ? entry.fileName : '',
  docTypeLabel: docTypeLabel,
  recipientName: recipientName,
  extractedFields: decision.extractedFields || {},
  matchReason: (decision.reason || '').toString(),
  outputFilenameBase: safeName + '_' + safeLabel,
  outputFilename: safeName + '_' + safeLabel + '.docx'
}) }];

const record = $input.first().json;
let md = '';
try {
  md = record.output[0].content[0].text || '';
} catch (e) {
  throw new Error('Could not find text in AI response. Structure received: ' + JSON.stringify(record).substring(0, 300));
}
if (!md) {
  throw new Error('AI returned an empty response.');
}
md = md.trim();
if (md.startsWith('```')) {
  md = md.replace(/^```[a-z]*\n?/, '').replace(/```\s*$/, '').trim();
}
const d = $('Parse Template Match Decision').first().json;
const dateStr = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
return [{ json: {
  markdownContent: md,
  outputFilename: d.outputFilename,
  outputFilenameBase: d.outputFilenameBase,
  docTypeLabel: d.docTypeLabel,
  recipientName: d.recipientName,
  senderEmail: d.senderEmail,
  senderName: d.senderName,
  messageId: d.messageId,
  subject: d.subject,
  outputFolderId: d.outputFolderId,
  pandocUrl: d.pandocUrl,
  pandocReferenceDoc: d.pandocReferenceDoc,
  companyName: d.companyName,
  dateStr: dateStr
} }];

