const upload = $input.first().json;
const meta = $('Parse AI Markdown Output').first().json;
const bin = $('Convert Markdown to DOCX').first().binary;
if (!bin || !bin.data) {
  throw new Error('DOCX binary not found from the Pandoc conversion step.');
}
const docx = Object.assign({}, bin.data, {
  fileName: meta.outputFilename,
  mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
});
return [{
  json: Object.assign({}, meta, { webUrl: upload.webViewLink || upload.webContentLink || '' }),
  binary: { data: docx }
}];
